public class InnerProjectProfileEnvironmentConfigurationFactory(Action<Humidifier.DataZone.ProjectProfileTypes.EnvironmentConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.DataZone.ProjectProfileTypes.EnvironmentConfiguration>
{

    internal InnerProjectProfileRegionFactory AwsRegionFactory { get; set; }

    internal InnerProjectProfileAwsAccountFactory AwsAccountFactory { get; set; }

    internal InnerProjectProfileEnvironmentConfigurationParametersDetailsFactory ConfigurationParametersFactory { get; set; }

    protected override Humidifier.DataZone.ProjectProfileTypes.EnvironmentConfiguration Create()
    {
        var environmentConfigurationResult = CreateEnvironmentConfiguration();
        factoryAction?.Invoke(environmentConfigurationResult);

        return environmentConfigurationResult;
    }

    private Humidifier.DataZone.ProjectProfileTypes.EnvironmentConfiguration CreateEnvironmentConfiguration()
    {
        var environmentConfigurationResult = new Humidifier.DataZone.ProjectProfileTypes.EnvironmentConfiguration();

        return environmentConfigurationResult;
    }
    public override void CreateChildren(Humidifier.DataZone.ProjectProfileTypes.EnvironmentConfiguration result)
    {
        base.CreateChildren(result);

        result.AwsRegion ??= AwsRegionFactory?.Build();
        result.AwsAccount ??= AwsAccountFactory?.Build();
        result.ConfigurationParameters ??= ConfigurationParametersFactory?.Build();
    }

} // End Of Class

